class ReadWriteOnce:
    """
    A class representing a read-write-once access pattern.
    """

    def __init__(self, value):
        self._value = value

    @property
    def value(self):
        """Get the current value."""
        return self._value

    @value.setter
    def value(self, new_value):
        """Set the value once."""
        if hasattr(self, '_is_set') and self._is_set:
            raise ValueError("Value can only be set once.")
        self._value = new_value
        self._is_set = True
