def get_different_subcloud(subclouds, exclude_ids=None, exclude_names=None):
    if exclude_ids is None:
        exclude_ids = []
    if exclude_names is None:
        exclude_names = []

    available_subclouds = [
        subcloud for subcloud in subclouds
        if subcloud.get_id() not in exclude_ids and subcloud.name not in exclude_names
    ]

    if not available_subclouds:
        raise ValueError("No different subclouds available")

    highest_subcloud = max(available_subclouds, key=lambda subcloud: int(subcloud.get_id()))
    return highest_subcloud
